private void permute(String n, List<Integer> current, List<List<Integer>> result, int[] original) {
    if (n.isEmpty()) {
        result.add(new ArrayList<>(current));
        return;
    }
    char c = n.charAt(0);
    n = n.substring(1);
    int index = original.indexOf((int) c);
    if (index == -1) {
        return;
    }
    original.remove(index);
    current.add((int) c);
    permute(n, current, result, original);
    current.remove(current.size() - 1);
    original.add(index, (int) c);
}
