public class SubstringFinder {
    public int findLargestSubstring(List<String> strings) {
        // Convert all strings to uppercase to ensure comparison is case-sensitive
        for (String str : strings) {
            str = str.toUpperCase();
        }

        int maxSubstringLength = 0;
        for (String str : strings) {
            for (int i = 1; i < str.length(); i++) {
                // Check for substring starting from i andending at str.length()
                String reversedSubstring = new StringBuilder(str.substring(i)).reverse().toString();

                // Check if reversed substring is present in any of the strings
                for (String otherStr : strings) {
                    if (otherStr.contains(reversedSubstring)) {
                        // Update maxSubstringLength if the current substring is longer
                        maxSubstringLength = Math.max(maxSubstringLength, i);
                        break;
                    }
                }
            }
        }

        return maxSubstringLength;
    }

