public class StringSorter {
    public String sortString(String s) {
        List<Character> sortedChars = new ArrayList<>();
        Set<Character> uniqueChars = new HashSet<>();

        // Count occurrences of each character
        for (char c : s.toCharArray()) {
            uniqueChars.add(c);
        }
        for (char c : uniqueChars) {
            sortedChars.add(c);
        }

        // Sort characters based on their frequency
        sortedChars.sort((a, b) -> Integer.compare(s.chars().filter(c -> c == a).count(), s.chars().filter(c -> c == b).count()));

        StringBuilder result = new StringBuilder();
        int i = 0, j = sortedChars.size() - 1;

        // Alternate between picking smallest and largest characters
        while (result.length() < s.length()) {
            if (i < sortedChars.size()) {
                result.append(sortedChars.get(i));
                i++;
            }
            if (j >= 0) {
                result.append(sortedChars.get(j));
                j--;
            }
        }

        return result.toString();
    }
}
