    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    if (totalSum == 0) {
        return false; // If total sum is zero, it's impossible to split the array evenly.
    }
    int requiredAverage = totalSum / (int) Math.ceil(nums.length / 2.0);
    boolean[] dp = new boolean[requiredAverage + 1];
