    public int minOperations(int n) {
        int result = 0;
        int midValue = n / 2;

        for (int i = 0; i <= n / 2; i++) {
            int leftValue = (2 * i) + 1;
            int rightValue = (2 * i + 1) + 1;

            if (leftValue != midValue && rightValue == midValue) {
                result += n - leftValue;
