private String[] split(String s, int position, int till)
{
    if(s == null || s.isEmpty())
        return new String[0];

    if(till == position)
    {
        return new String[]{s};
    }

    String[] heads = split(s, position + 1, till);
    String[] tails = split(s.substring(position + 1), 0, till);

    String[] results = new String[ heads.length + tails.length ];
    // Insert current element in between heads
    int headInd = 0;
    for(String head : heads)
    {
        results[headInd++] = head;
    }

    // Insert current element in between tails
    int tailInd = 0;
    int index = headInd;
    while(index < results.length)
    {
        results[index++] = s.substring(position, position + 1) + tails[tailInd++];
    }

    return results;
}

