import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n < 2) {
        return 1; // A empty array or a single element is always a square permutation.
    }

    Map<Integer, Set<Integer>> map = new HashMap<>();
    Set<Integer> visited = new HashSet<>();

    // Seed the map with the first element and its square.
    int first = A[0];
    map.put(first, new HashSet<Integer>());
    map.get(first).add(getSquare(first));

    for (int i = 1; i < n; i++) {
        int current = A[i];
        int currentSquare = getSquare(current);

        // Add the current number to the map if the square is not in it already.
        if (!map.containsKey(currentSquare)) {
            map.put(currentSquare, new HashSet<Integer>());
        }

        // Check all previous numbers to see if they can form a square permutation pair.
        for (int prev : map.get(first)) {
            if (isPerfectSquare(current + prev)) {
                map.get(currentSquare).add(current);
                map.get(currentSquare).add(prev);
                visited.add(prev);
            }
        }

        // Move to the next previous number.
        visited.add(first);
        first = current;
    }

    int count = 0;
    // Count the number of valid square permutations.
    for (int square : map.keySet()) {
        count += map.get(square).size();
    }

    return count;
}

private static int getSquare(int n) {
    return n * n;
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}
