public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int sqrt = (int) Math.sqrt(n);
    int min = n, count = 0;

    do {
        count++;
        int square = sqrt * sqrt;
        int difference = n - square;
        if (difference < min) {
            min = difference;
        }
        n = difference;
        sqrt = (int) Math.sqrt(n);
    } while (sqrt * sqrt <= n);

    return min + count;
}
